import { Dialog as AriaDialog, Heading, Modal, useDialogDescription } from "@barqjs/aria/dialog";
import type { Incoming } from "@barqjs/core";
import { firstThatWorks, layer } from "@barqjs/css";

import "../theme/layers.ts";
import { box } from "../lib/shared-box.ts";
import { when } from "../lib/shared-when.ts";
import { text } from "../lib/shared-text.ts";
import {
  overlayFamily,
  OverlayPortal,
  registerUnderlay,
  type OverlayPortalProps,
  type OverlayRootProps,
} from "../lib/overlay.tsx";
import type { UiProps } from "../lib/props.ts";
import type { TriggerPartProps } from "../lib/trigger.tsx";
import { handedOn, named, uiProps } from "../lib/slot.ts";
import { Button, type ButtonProps } from "./button.tsx";

const ui = layer("barq.ui");

const overlay = ui({
  position: "fixed",
  inset: "0px",
  zIndex: "50",
  animation:
    "enter var(--ui-animation-duration, var(--ui-duration, 0.15s)) var(--ui-ease, ease) var(--ui-animation-delay, 0s) var(--ui-animation-iteration-count, 1) var(--ui-animation-direction, normal) var(--ui-animation-fill-mode, none)",
  backgroundColor: "color-mix(in srgb, #000 10%, transparent)",
  "--ui-duration": "100ms",
  transitionDuration: "100ms",
  "--ui-enter-opacity": firstThatWorks("0", "calc(0/100)"),
  "@supports (color: color-mix(in lab, red, red))": {
    backgroundColor: "color-mix(in oklab, var(--color-black) 10%, transparent)",
  },
  "@supports (backdrop-filter: var(--tw))": {
    "&": {
      "--ui-backdrop-blur": "blur(var(--blur-xs))",
      "-webkit-backdrop-filter":
        "var(--ui-backdrop-blur,) var(--ui-backdrop-brightness,) var(--ui-backdrop-contrast,) var(--ui-backdrop-grayscale,) var(--ui-backdrop-hue-rotate,) var(--ui-backdrop-invert,) var(--ui-backdrop-opacity,) var(--ui-backdrop-saturate,) var(--ui-backdrop-sepia,)",
      backdropFilter:
        "var(--ui-backdrop-blur,) var(--ui-backdrop-brightness,) var(--ui-backdrop-contrast,) var(--ui-backdrop-grayscale,) var(--ui-backdrop-hue-rotate,) var(--ui-backdrop-invert,) var(--ui-backdrop-opacity,) var(--ui-backdrop-saturate,) var(--ui-backdrop-sepia,)",
    },
  },
  "[data-closed]": {
    animation:
      "exit var(--ui-animation-duration, var(--ui-duration, 0.15s)) var(--ui-ease, ease) var(--ui-animation-delay, 0s) var(--ui-animation-iteration-count, 1) var(--ui-animation-direction, normal) var(--ui-animation-fill-mode, none)",
    "--ui-animation-fill-mode": "forwards",
    "--ui-exit-opacity": firstThatWorks("0", "calc(0/100)"),
  },
});

const header = ui({
  display: "grid",
  gridTemplateRows: "auto 1fr",
  placeItems: "center",
  gap: "calc(var(--spacing) * 1.5)",
  textAlign: "center",
  ':has([data-slot="alert-dialog-media"])': {
    gridTemplateRows: "auto auto 1fr",
    columnGap: "calc(var(--spacing) * 4)",
  },
  "@media (width >= 40rem)": {
    '[data-slot="alert-dialog-content"][data-size="default"] &': {
      placeItems: "start",
      textAlign: "start",
    },
    '[data-slot="alert-dialog-content"][data-size="default"] &:has([data-slot="alert-dialog-media"])':
      {
        gridTemplateRows: "auto 1fr",
      },
  },
});

// Pulled out to the content's edges and given its bottom corners, so the
// muted band reaches the sides rather than floating inside the padding.
const footer = ui({
  marginInline: "calc(var(--spacing) * -4)",
  marginBottom: "calc(var(--spacing) * -4)",
  display: "flex",
  flexDirection: "column-reverse",
  gap: "calc(var(--spacing) * 2)",
  borderEndEndRadius: "calc(var(--radius) * 1.4)",
  borderEndStartRadius: "calc(var(--radius) * 1.4)",
  borderTopStyle: "var(--ui-border-style)",
  borderTopWidth: "1px",
  backgroundColor: "var(--muted)",
  padding: "calc(var(--spacing) * 4)",
  "@supports (color: color-mix(in lab, red, red))": {
    backgroundColor: "color-mix(in oklab, var(--muted) 50%, transparent)",
  },
  "@media (width >= 40rem)": {
    "&": {
      flexDirection: "row",
      justifyContent: "flex-end",
    },
  },
  '[data-slot="alert-dialog-content"][data-size="sm"] &': {
    display: "grid",
    gridTemplateColumns: "repeat(2, minmax(0, 1fr))",
  },
});

const title = ui(text.heading, text.medium, {
  fontSize: "var(--text-base)",
  lineHeight: "var(--ui-leading, var(--text-base--line-height))",
  "@media (width >= 40rem)": {
    '[data-slot="alert-dialog-content"][data-size="default"]:has([data-slot="alert-dialog-media"]) &':
      {
        gridColumnStart: "2",
      },
  },
});

const description = ui(text.sm, {
  textWrap: "balance",
  color: "var(--muted-foreground)",
  "@media (width >= 48rem)": {
    "&": {
      textWrap: "pretty",
    },
  },
  ":is(& > *):is(a)": {
    textDecorationLine: "underline",
    textUnderlineOffset: "3px",
  },
  "@media (hover: hover)": {
    ":is(& > *):is(a):hover": {
      color: "var(--foreground)",
    },
  },
});

const media = ui({
  marginBottom: "calc(var(--spacing) * 2)",
  display: "inline-flex",
  width: "calc(var(--spacing) * 10)",
  height: "calc(var(--spacing) * 10)",
  alignItems: "center",
  justifyContent: "center",
  borderRadius: "calc(var(--radius) * 0.8)",
  backgroundColor: "var(--muted)",
  '& > svg:not([class*="size-"])': {
    width: "calc(var(--spacing) * 6)",
    height: "calc(var(--spacing) * 6)",
  },
  "@media (width >= 40rem)": {
    '[data-slot="alert-dialog-content"][data-size="default"] &': {
      gridRow: "span 2 / span 2",
    },
  },
});

export type AlertDialogSize = "default" | "sm";

/** The size is an attribute the CSS reads, so there is one class and not two. */
const content = ui(box.shadow, box.outline, when.closing, {
  position: "fixed",
  top: "calc(1 / 2 * 100%)",
  left: "calc(1 / 2 * 100%)",
  zIndex: "50",
  display: "grid",
  width: "100%",
  "--ui-translate-x": "calc(calc(1 / 2 * 100%) * -1)",
  translate: "var(--ui-translate-x) var(--ui-translate-y)",
  "--ui-translate-y": "calc(calc(1 / 2 * 100%) * -1)",
  animation:
    "enter var(--ui-animation-duration, var(--ui-duration, 0.15s)) var(--ui-ease, ease) var(--ui-animation-delay, 0s) var(--ui-animation-iteration-count, 1) var(--ui-animation-direction, normal) var(--ui-animation-fill-mode, none)",
  gap: "calc(var(--spacing) * 4)",
  borderRadius: "calc(var(--radius) * 1.4)",
  backgroundColor: "var(--popover)",
  padding: "calc(var(--spacing) * 4)",
  color: "var(--popover-foreground)",
  "--ui-ring-shadow":
    "var(--ui-ring-inset,) 0 0 0 calc(1px + var(--ui-ring-offset-width)) var(--ui-ring-color, currentcolor)",
  "--ui-ring-color": "var(--foreground)",
  "--ui-duration": "100ms",
  transitionDuration: "100ms",
  "--ui-enter-opacity": firstThatWorks("0", "calc(0/100)"),
  "--ui-enter-scale": firstThatWorks("0.95", "calc(95*1%)"),
  "@supports (color: color-mix(in lab, red, red))": {
    "--ui-ring-color": "color-mix(in oklab, var(--foreground) 10%, transparent)",
  },
  '[data-size="default"]': {
    maxWidth: "var(--container-xs)",
  },
  '[data-size="sm"]': {
    maxWidth: "var(--container-xs)",
  },
  "@media (width >= 40rem)": {
    '[data-size="default"]': {
      maxWidth: "var(--container-sm)",
    },
  },
});

const family = overlayFamily("AlertDialog");

export interface AlertDialogProps extends OverlayRootProps {}

/**
 * A dialog that interrupts, for a choice that cannot be dismissed by ignoring
 * it.
 *
 * `role="alertdialog"`, and neither an outside press nor Escape closes it: the
 * user has to answer. That is the whole difference from `<Dialog>`, and it is
 * why the close button in the corner is not here either.
 *
 * ```tsx
 * <AlertDialog>
 *   <AlertDialogTrigger><Button variant="destructive">Delete</Button></AlertDialogTrigger>
 *   <AlertDialogContent>
 *     <AlertDialogHeader>
 *       <AlertDialogTitle>Delete the project?</AlertDialogTitle>
 *       <AlertDialogDescription>This cannot be undone.</AlertDialogDescription>
 *     </AlertDialogHeader>
 *     <AlertDialogFooter>
 *       <AlertDialogCancel>Cancel</AlertDialogCancel>
 *       <AlertDialogAction variant="destructive" onPress={remove}>Delete</AlertDialogAction>
 *     </AlertDialogFooter>
 *   </AlertDialogContent>
 * </AlertDialog>
 * ```
 */
export function AlertDialog(props: Incoming<AlertDialogProps>) {
  return <family.Root {...props} />;
}

export function AlertDialogTrigger(props: Incoming<TriggerPartProps>) {
  return <family.Trigger {...props} />;
}

export interface AlertDialogPortalProps extends OverlayPortalProps {}

/** Names the container the alert dialog inside is rendered into. See `<DialogPortal>`. */
export function AlertDialogPortal(props: Incoming<AlertDialogPortalProps>) {
  return <OverlayPortal {...props} />;
}

/** What the element behind the alert dialog looks like and carries. See `<DialogOverlay>`. */
export function AlertDialogOverlay(props: Incoming<UiProps>) {
  registerUnderlay(family.use(), uiProps("alert-dialog-overlay", overlay, props));
  return <></>;
}

export interface AlertDialogContentProps extends UiProps {
  /** @default "default" */
  size?: AlertDialogSize;
}

export function AlertDialogContent(props: Incoming<AlertDialogContentProps>) {
  const { state, underlay } = family.use();

  return (
    <Modal
      isOpen={state.isOpen()}
      onOpenChange={state.setOpen}
      // A press outside decides nothing, which is what makes it an ALERT
      // dialog. Escape still closes it: Radix prevents only the outside
      // interaction, and the APG asks for Escape on every dialog, alert or not.
      isDismissable={false}
      underlayClass={underlay() === null ? overlay : undefined}
      underlaySlot="alert-dialog-overlay"
      underlayProps={underlay() ?? undefined}
      {...handedOn(props)}
      class={ui(content, props.class?.(), props.className?.())}
      data-slot={props["data-slot"]?.() ?? "alert-dialog-content"}
      data-size={props.size?.() ?? "default"}
    >
      <AriaDialog {...named(props)} role="alertdialog" class={contents}>
        {props.children}
      </AriaDialog>
    </Modal>
  );
}

/** See `dialog.tsx`: the dialog's own element lays nothing out. */
const contents = ui({
  display: "contents",
});

export function AlertDialogHeader(props: Incoming<UiProps>) {
  return <div {...uiProps("alert-dialog-header", header, props)}>{props.children}</div>;
}

export function AlertDialogFooter(props: Incoming<UiProps>) {
  return <div {...uiProps("alert-dialog-footer", footer, props)}>{props.children}</div>;
}

/** An icon above the title, for the one that says what kind of interruption this is. */
export function AlertDialogMedia(props: Incoming<UiProps>) {
  return <div {...uiProps("alert-dialog-media", media, props)}>{props.children}</div>;
}

export function AlertDialogTitle(props: Incoming<UiProps>) {
  return (
    <Heading
      {...props}
      slot="title"
      data-slot={props["data-slot"]?.() ?? "alert-dialog-title"}
      class={ui(title, props.class?.(), props.className?.())}
    />
  );
}

export function AlertDialogDescription(props: Incoming<UiProps>) {
  const described = useDialogDescription();
  // The dialog points at this element, and only because the hook was called:
  // a description nothing references is read by whoever goes looking for it
  // and by nobody else.
  return (
    <p
      {...uiProps("alert-dialog-description", description, props)}
      id={props.id?.() ?? described?.id()}
    >
      {props.children}
    </p>
  );
}

export interface AlertDialogActionProps extends ButtonProps {}

/** The button that does the thing. It closes the dialog after its own handler. */
export function AlertDialogAction(props: Incoming<AlertDialogActionProps>) {
  const { state } = family.use();
  return (
    <Button
      {...props}
      data-slot={props["data-slot"]?.() ?? "alert-dialog-action"}
      onPress={(event) => {
        props.onPress?.()?.(event);
        state.close();
      }}
    />
  );
}

/** The button that does not. Outlined by default, which is shadcn's arrangement. */
export function AlertDialogCancel(props: Incoming<AlertDialogActionProps>) {
  const { state } = family.use();
  return (
    <Button
      {...props}
      data-slot={props["data-slot"]?.() ?? "alert-dialog-cancel"}
      variant={props.variant?.() ?? "outline"}
      onPress={(event) => {
        props.onPress?.()?.(event);
        state.close();
      }}
    />
  );
}
